<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT s.* FROM students s JOIN batches b ON b.id=s.batch_id WHERE s.id=? AND b.department_id=?');$q->execute([$id,$_SESSION['user']['department_id']]);$s=$q->fetch();if(!$s)redirect('/hod/students/index.php');if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();db()->prepare('UPDATE students SET student_name=?,email=?,phone=?,status=? WHERE id=?')->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),$_POST['status'],$id]);flash('Student updated.');redirect('/hod/students/index.php?batch_id='.$s['batch_id']);}$title='Edit Student';require __DIR__.'/../../includes/header.php';?><section class="panel"><h2><?=e($s['registration_number'])?></h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="name" value="<?=e($s['student_name'])?>"></label><label>Email<input type="email" name="email" value="<?=e($s['email'])?>"></label><label>Phone<input name="phone" value="<?=e($s['phone'])?>"></label><label>Status<select name="status"><option><?=e($s['status'])?></option><option value="<?=$s['status']==='active'?'inactive':'active'?>"><?=$s['status']==='active'?'inactive':'active'?></option></select></label><button>Update Student</button></form></section><?php require __DIR__.'/../../includes/footer.php';?>
